std::wstring Wide(const std::string& s){const int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),nullptr,0);if(n<=0&&!s.empty())throw std::invalid_argument("Invalid UTF-8 text.");std::wstring w(static_cast<std::size_t>(n),0);if(n)MultiByteToWideChar(CP_UTF8,0,s.data(),static_cast<int>(s.size()),w.data(),n);return w;}
std::wstring Text(HWND w){const int n=GetWindowTextLengthW(w);std::wstring s(static_cast<std::size_t>(n)+1,0);GetWindowTextW(w,s.data(),n+1);s.resize(static_cast<std::size_t>(n));return s;}
std::string Read(const std::wstring& path){std::ifstream in(std::filesystem::path(path),std::ios::binary|std::ios::ate);if(!in)throw std::runtime_error("Cannot open the selected recording.");const auto size=in.tellg();if(size<0||size>32*1024*1024)throw std::runtime_error("Recording exceeds 32 MiB.");in.seekg(0);std::string s(static_cast<std::size_t>(size),'\0');if(!s.empty()&&!in.read(s.data(),size))throw std::runtime_error("Recording read failed.");return s;}
void Write(const std::wstring& path,const std::string& s){std::ofstream out(std::filesystem::path(path),std::ios::binary|std::ios::trunc);if(!out||!out.write(s.data(),static_cast<std::streamsize>(s.size())))throw std::runtime_error("File write failed.");}
std::wstring Choose(HWND owner,bool save,bool csv=false){wchar_t path[32768]=L"recording.json";if(csv)wcscpy_s(path,L"recording.csv");OPENFILENAMEW f{sizeof(f)};f.hwndOwner=owner;f.lpstrFilter=csv?L"Event CSV\0*.csv\0All files\0*.*\0":L"Input recording JSON\0*.json\0All files\0*.*\0";f.lpstrFile=path;f.nMaxFile=32768;f.lpstrDefExt=csv?L"csv":L"json";f.Flags=OFN_EXPLORER|OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);return (save?GetSaveFileNameW(&f):GetOpenFileNameW(&f))?path:L"";}
std::filesystem::path Directory(){wchar_t path[32768]{};GetModuleFileNameW(nullptr,path,32768);return std::filesystem::path(path).parent_path();}
bool Admin(){SID_IDENTIFIER_AUTHORITY a=SECURITY_NT_AUTHORITY;PSID g=nullptr;BOOL yes=FALSE;if(AllocateAndInitializeSid(&a,2,SECURITY_BUILTIN_DOMAIN_RID,DOMAIN_ALIAS_RID_ADMINS,0,0,0,0,0,0,&g)){CheckTokenMembership(nullptr,g,&yes);FreeSid(g);}return yes!=FALSE;}
