    int P(int n)const{return MulDiv(n,static_cast<int>(dpi_),96);}
    void ScaleFonts(UINT next){const auto scaled=[&](HFONT old){LOGFONTW f{};GetObjectW(old,sizeof(f),&f);f.lfHeight=MulDiv(f.lfHeight,static_cast<int>(next),static_cast<int>(dpi_));return CreateFontIndirectW(&f);};const auto normal=scaled(font_),mono=scaled(mono_),title=scaled(title_);if(!normal||!mono||!title){DeleteObject(normal);DeleteObject(mono);DeleteObject(title);return;}const auto old=font_,oldMono=mono_,oldTitle=title_;font_=normal;mono_=mono;title_=title;dpi_=next;for(const auto& c:controls_)SendMessageW(c.first,WM_SETFONT,reinterpret_cast<WPARAM>(font_),TRUE);SendMessageW(timeline_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),TRUE);DeleteObject(old);DeleteObject(oldMono);DeleteObject(oldTitle);}
