    void ShowDocument(std::shared_ptr<const Replay::Recording> doc){if(doc==shown_)return;shown_=std::move(doc);std::wstring text=L"Time                 Captured event\r\n\r\n";if(shown_){const auto count=(std::min)(shown_->events.size(),std::size_t(1000));for(std::size_t i=0;i<count;++i)text+=Wide(Replay::Describe(shown_->events[i]))+L"\r\n";if(shown_->events.size()>count)text+=L"\r\nShowing first 1000 events. JSON/CSV exports contain the full recording.";}else text+=L"No finished recording. Choose one device, then Record and Stop.\r\nLoad JSON can be used without opening the driver.";SetWindowTextW(timeline_,text.c_str());}
