        if(id==Setup){const auto path=Directory()/L"Dependencies"/L"InterceptorSetup.exe";if(!std::filesystem::exists(path))throw std::runtime_error("Dependencies/InterceptorSetup.exe is missing. Extract the complete release ZIP.");ShellExecuteW(window_,L"open",path.c_str(),nullptr,path.parent_path().c_str(),SW_SHOWNORMAL);return;}
        if(id==Save||id==Csv){if(state_.recording)throw std::runtime_error("Stop the recording before exporting it.");if(!state_.document)throw std::runtime_error("Record or load a timeline first.");const auto path=Choose(window_,true,id==Csv);if(!path.empty()){Write(path,id==Csv?Replay::Csv(*state_.document):Replay::Serialize(*state_.document));Status(L"Export completed. Recorded inputs remain local unless you share the file.");}return;}
