public:
    explicit Window(bool preview):preview_(preview){}
    ~Window(){engine_.Close();DeleteObject(font_);DeleteObject(mono_);DeleteObject(title_);DeleteObject(background_);DeleteObject(panel_);}
    void Open(){WNDCLASSW c{};c.hInstance=GetModuleHandleW(nullptr);c.lpfnWndProc=Proc;c.lpszClassName=L"InputReplayLab.Window";c.hCursor=LoadCursorW(nullptr,IDC_ARROW);c.hIcon=LoadIconW(nullptr,IDI_APPLICATION);RegisterClassW(&c);window_=CreateWindowExW(0,c.lpszClassName,L"Input Replay Lab",WS_OVERLAPPEDWINDOW,CW_USEDEFAULT,CW_USEDEFAULT,1200,820,nullptr,nullptr,c.hInstance,this);if(!window_)throw std::runtime_error("Window creation failed.");SetWindowPos(window_,nullptr,0,0,P(1200),P(820),SWP_NOMOVE|SWP_NOZORDER);BOOL dark=TRUE;DwmSetWindowAttribute(window_,20,&dark,sizeof(dark));ShowWindow(window_,SW_SHOW);UpdateWindow(window_);}
